--
-- Table structure for table `Stores`
--

DROP TABLE IF EXISTS `Stores`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `Stores` (
  `id` int NOT NULL AUTO_INCREMENT,
  `store_name` varchar(255) NOT NULL,
  `area` varchar(255) DEFAULT NULL,
  `city_id` int NOT NULL,
  `region_id` int NOT NULL,
  `ba_user_id` int DEFAULT NULL,
  `targets` decimal(10,2) DEFAULT '0.00',
  `poc` varchar(255) DEFAULT NULL,
  `store_manager_name` varchar(255) DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `channel_id` int DEFAULT NULL,
  `supervisor_id` int DEFAULT NULL,
  `ba_user_id_2` int DEFAULT NULL,
  `ba_user_id_3` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `city_id` (`city_id`),
  KEY `region_id` (`region_id`),
  KEY `ba_user_id` (`ba_user_id`),
  KEY `stores_channel_id_index` (`channel_id`),
  KEY `Stores_supervisor_id_foreign_idx` (`supervisor_id`),
  KEY `Stores_ba_user_id_2_foreign_idx` (`ba_user_id_2`),
  KEY `Stores_ba_user_id_3_foreign_idx` (`ba_user_id_3`),
  CONSTRAINT `Stores_ba_user_id_2_foreign_idx` FOREIGN KEY (`ba_user_id_2`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Stores_ba_user_id_3_foreign_idx` FOREIGN KEY (`ba_user_id_3`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Stores_channel_id_foreign_idx` FOREIGN KEY (`channel_id`) REFERENCES `Channels` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Stores_ibfk_1` FOREIGN KEY (`city_id`) REFERENCES `Cities` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `Stores_ibfk_2` FOREIGN KEY (`region_id`) REFERENCES `Regions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `Stores_ibfk_3` FOREIGN KEY (`ba_user_id`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE,
  CONSTRAINT `Stores_supervisor_id_foreign_idx` FOREIGN KEY (`supervisor_id`) REFERENCES `Users` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=128 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

