DROP TABLE IF EXISTS `interceptions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `interceptions` (
  `id` int NOT NULL AUTO_INCREMENT,
  `report_date` date NOT NULL,
  `intercepted` int NOT NULL DEFAULT '0',
  `converted` int NOT NULL DEFAULT '0',
  `ratio` decimal(5,2) NOT NULL DEFAULT '0.00',
  `ba_user_id` int NOT NULL,
  `store_id` int NOT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `ba_user_id` (`ba_user_id`),
  KEY `store_id` (`store_id`),
  CONSTRAINT `interceptions_ibfk_1` FOREIGN KEY (`ba_user_id`) REFERENCES `Users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `interceptions_ibfk_2` FOREIGN KEY (`store_id`) REFERENCES `Stores` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6839 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

